update interview_records set nonverbal = jsonb_set(nonverbal, '{awayPct}', to_jsonb(100 - (nonverbal->>'frontPct')::int - (nonverbal->>'downPct')::int))
  || jsonb_build_object('items', (select jsonb_agg(it || jsonb_build_object('awayPct', greatest(0, 100 - (it->>'frontPct')::int - (it->>'downPct')::int)) || case when (it->>'frontPct')::int + (it->>'downPct')::int > 100 then jsonb_build_object('frontPct', 100 - (it->>'downPct')::int) else '{}'::jsonb end order by (it->>'i')::int) from jsonb_array_elements(nonverbal->'items') it))
 where user_id='7e570000-0000-4000-8000-000000000021' and created_at in ('2026-10-20 10:40:49+00','2026-10-22 11:15:58+00','2026-10-24 12:05:45+00','2026-10-27 10:20:54+00','2026-10-29 11:30:37+00','2026-11-01 05:10:19+00','2026-11-03 10:50:51+00','2026-11-05 11:40:50+00','2026-11-07 12:10:18+00','2026-11-10 10:30:30+00','2026-11-12 11:20:13+00','2026-11-13 10:45:45+00','2026-11-15 06:30:55+00','2026-11-16 11:10:29+00','2026-11-17 10:25:08+00') and nonverbal ? 'items';
